tool_args.command:
python3 -c "
import json, re
pat = re.compile(r'\[ERROR\]\s+(\w+)\s+at\s+line\s+(\d+):\s*(.*?)\s*\|\s*locals:\s*(.*)')
total_err = 0; matched = 0; no_error_fail = 0; total_fail = 0
with open('/root/autodl-tmp/trace-verdict-study-data/exception_only_train.jsonl') as f:
    for line in f:
        d = json.loads(line)
        if d['output'] == 'fail':
            total_fail += 1
            if '[ERROR]' not in d['input']:
                no_error_fail += 1
                continue
            for l in d['input'].split('\n'):
                if l.startswith('[ERROR]'):
                    total_err += 1
                    if pat.match(l):
                        matched += 1
print(f'total_fail={total_fail}, no_error_fail={no_error_fail}')
print(f'ERROR lines: total={total_err}, regex_matched={matched}, rate={matched/total_err*100:.1f}%' if total_err else 'no error lines')
"
